// What the escalation clock did on this run (reminders, escalations, holds). The database already wrote the notifications.
const rows = $input.all().map(i => i.json).filter(r => r && r.t_event_id);
const count = k => rows.filter(r => r.t_action === k).length;
return [{ json: { ran_at: new Date().toISOString(), actions: rows.length, reminders: count('REMINDER'),
  escalations: count('ESCALATED'), held: count('HELD'),
  detail: rows.map(r => ({ event_id: r.t_event_id, action: r.t_action, from: r.t_from_level, to: r.t_to_level, deadline: r.t_deadline })) } }];

// Format claimed notifications by kind. Each message carries the routed email address (null when no route is configured).
const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const tag = { APPROVAL_REQUEST: 'APPROVAL NEEDED', REMINDER: 'REMINDER', ESCALATED: 'ESCALATED', HELD: 'HELD - HUMAN DECISION NEEDED', PRODUCTION: 'PRODUCTION PLANNING', DECIDED: 'DECIDED' };
const clean = v => String(v ?? '').replace(/[\r\n\t]+/g, ' ').trim();
const messages = rows.map(r => {
  const label = tag[r.kind] || clean(r.kind);
  const email = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(clean(r.email)) ? clean(r.email) : null;
  return { id: Number(r.id), kind: r.kind, to: clean(r.recipient), email, event_id: r.event_id, attempts: Number(r.attempts || 0),
    subject: `[SCM] ${label}: ${clean(r.subject)}`.slice(0, 200),
    plain: `${clean(r.body)}\n\nEvent: ${clean(r.event_id)}\nRecipient role: ${clean(r.recipient)}\nSent by the Supply Chain Disruption crew (SOP-SC-015).`,
    text: `[${label}] ${clean(r.subject)} - ${clean(r.body)}` };
});
return [{ json: { count: messages.length, ids: messages.map(m => m.id), messages } }];

// One item per message that has an email route; a single {skip:true} item when there is nothing to send.
const msgs = ($input.first().json.messages || []).filter(m => m.email);
if (!msgs.length) return [{ json: { skip: true } }];
return msgs.map(m => ({ json: { skip: false, id: m.id, email: m.email, subject: m.subject, plain: m.plain } }));

// Decide which claimed notifications are finished. Sent ok -> finished. No email route -> finished (logged only).
// Send failed -> left CLAIMED so notify_claim re-offers it after 10 minutes, but given up after 5 attempts (never an endless loop).
const MAX_ATTEMPTS = 5;
const msgs = $('Format notifications').first().json.messages || [];
let sent = [];
try { sent = $('Send email').all(); } catch (e) { sent = []; }   // the node did not run: there was nothing to send
const sendable = msgs.filter(m => m.email);
const ok = new Set();
sendable.forEach((m, i) => { const out = (sent[i] || {}).json || {}; if (out.id && !out.error) ok.add(m.id); });
const done = [], failed = [], noRoute = [];
for (const m of msgs) {
  if (!m.email) { noRoute.push(m.id); done.push(m.id); }
  else if (ok.has(m.id)) done.push(m.id);
  else if (m.attempts >= MAX_ATTEMPTS) { failed.push({ id: m.id, gave_up: true }); done.push(m.id); }
  else failed.push({ id: m.id, gave_up: false });
}
return [{ json: { ids: done, emailed: ok.size, logged_only: noRoute.length, failed } }];

// Final answer of the tick workflow (also the HTTP body when it is started through its webhook).
const tick = $('Summarize tick').first().json;
const sent = $('Format notifications').first().json;
const res = $('Collect results').first().json;
const marked = $input.first().json || {};
return [{ json: { ...tick, notifications_dispatched: sent.count, notifications_marked_logged: marked.marked ?? 0,
  emailed: res.emailed, logged_only: res.logged_only, email_failures: res.failed,
  messages: sent.messages.map(m => ({ id: m.id, to: m.to, routed_to_email: !!m.email, text: m.text })),
  delivery: 'email through the SCM Gmail credential where a route exists (notification_routes); always logged in notification_outbox and the n8n execution' } }];
